using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

var builder = Host.CreateApplicationBuilder(args);

// Logging must go to stderr — stdout is reserved for JSON-RPC protocol messages.
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

builder.Services.AddHttpClient("MyApi", client =>
{
    client.BaseAddress = new Uri("https://api.example.com");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

builder.Services.AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(IHttpClientFactory httpClientFactory, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Retrieve a resource by its unique identifier.")]
    public async Task<string> GetResource(
        [Description("The unique identifier of the resource to fetch")] string resourceId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching resource {ResourceId}", resourceId);
        var client = httpClientFactory.CreateClient("MyApi");
        var response = await client.GetAsync($"/resources/{resourceId}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("Search resources by keyword query. Returns a JSON array of matching results.")]
    public async Task<string> SearchResources(
        [Description("Search keyword or phrase")] string query,
        [Description("Maximum number of results to return (1-50)")] int limit = 10,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching resources: {Query}, limit={Limit}", query, limit);
        var client = httpClientFactory.CreateClient("MyApi");
        var response = await client.GetAsync(
            $"/resources?q={Uri.EscapeDataString(query)}&limit={limit}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool(ReadOnly = false), Description("Create a new resource with the given name and content.")]
    public async Task<string> CreateResource(
        [Description("Display name for the new resource")] string name,
        [Description("Body content of the resource")] string content,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating resource: {Name}", name);
        var client = httpClientFactory.CreateClient("MyApi");
        var payload = JsonSerializer.Serialize(new { name, content });
        var httpContent = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");
        var response = await client.PostAsync("/resources", httpContent, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

